// The "postFormatter" option
createFailedTestCase(
  "postFormatter",
  {
    debug: true,
  },
  (msg) => expect(msg).toMatchSnapshot(),
  {
    name: "Webpack",
    baseDataPath: "configuration",
    postFormatter: (formattedError, error) => {
      if (
        error.keyword === "additionalProperties" &&
        !error.dataPath &&
        error.params.additionalProperty === "debug"
      ) {
        return (
          `${formattedError}\n` +
          "The 'debug' property was removed in webpack 2.0.0.\n" +
          "Loaders should be updated to allow passing this option via loader options in module.rules.\n" +
          "Until loaders are updated one can use the LoaderOptionsPlugin to switch loaders into debug mode:\n" +
          "plugins: [\n" +
          "  new webpack.LoaderOptionsPlugin({\n" +
          "    debug: true\n" +
          "  })\n" +
          "]"
        );
      }

      return formattedError;
    },
  }
);

createFailedTestCase(
  "postFormatter #1",
  {
    minify: true,
  },
  (msg) => expect(msg).toMatchSnapshot(),
  {
    name: "Webpack",
    baseDataPath: "configuration",
    postFormatter: (formattedError, error) => {
      if (
        error.keyword === "additionalProperties" &&
        !error.dataPath &&
        error.params.additionalProperty
      ) {
        return (
          `${formattedError}\n` +
          "For typos: please correct them.\n" +
          "For loader options: webpack >= v2.0.0 no longer allows custom properties in configuration.\n" +
          "  Loaders should be updated to allow passing options via loader options in module.rules.\n" +
          "  Until loaders are updated one can use the LoaderOptionsPlugin to pass these options to the loader:\n" +
          "  plugins: [\n" +
          "    new webpack.LoaderOptionsPlugin({\n" +
          "      // test: /\\.xxx$/, // may apply this only for some modules\n" +
          "      options: {\n" +
          `        ${error.params.additionalProperty}: …\n` +
          "      }\n" +
          "    })\n" +
          "  ]"
        );
      }

      return formattedError;
    },
  }
);

createFailedTestCase(
  "postFormatter #2",
  {
    entry: "foo.js",
    output: {
      filename: "/bar",
    },
  },
  (msg) => expect(msg).toMatchSnapshot(),
  {
    name: "Webpack",
    baseDataPath: "configuration",
    postFormatter: (formattedError, error) => {
      if (
        error.children &&
        error.children.some(
          (child) =>
            child.keyword === "absolutePath" &&
            child.instancePath === "/output/filename"
        )
      ) {
        return (
          `${formattedError}\n` +
          "Please use output.path to specify absolute path and output.filename for the file name."
        );
      }

      return formattedError;
    },
  }
);

